package org.dcl.merchantproductapp.servlet;
import java.io.IOException;import java.util.List;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;
import org.dcl.merchantproductapp.dao.ProductDao;import org.dcl.merchantproductapp.dto.Product;
@WebServlet("/products") public class ProductServlet extends HttpServlet {
 private ProductDao dao; public void init(){dao=new ProductDao();}
 private Integer merchantId(HttpServletRequest r){HttpSession s=r.getSession(false);Object id=s==null?null:s.getAttribute("merchantId");return id instanceof Integer?(Integer)id:null;}
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{Integer id=merchantId(req);if(id==null){resp.sendRedirect(req.getContextPath()+"/login.jsp");return;}try{List<Product> ps=dao.findProductsByMerchantId(id);req.setAttribute("products",ps);req.getRequestDispatcher("/products.jsp").forward(req,resp);}catch(Exception e){throw new ServletException("Unable to load products. Check server console.",e);}}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{Integer id=merchantId(req);if(id==null){resp.sendRedirect(req.getContextPath()+"/login.jsp");return;}req.setCharacterEncoding("UTF-8");String name=req.getParameter("name"),brand=req.getParameter("brand"),cat=req.getParameter("category"),priceText=req.getParameter("price");if(blank(name)||blank(brand)||blank(cat)||blank(priceText)){req.setAttribute("error","Complete all fields.");req.getRequestDispatcher("/add-product.jsp").forward(req,resp);return;}try{double price=Double.parseDouble(priceText);if(!Double.isFinite(price)||price<0)throw new NumberFormatException();Product p=new Product();p.setName(name.trim());p.setBrand(brand.trim());p.setCategory(cat.trim());p.setPrice(price);Product saved=dao.addProduct(id,p);if(saved==null){req.setAttribute("error","Merchant not found; product was not saved.");req.getRequestDispatcher("/add-product.jsp").forward(req,resp);return;}resp.sendRedirect(req.getContextPath()+"/products?added=1");}catch(NumberFormatException e){req.setAttribute("error","Enter a valid non-negative price.");req.getRequestDispatcher("/add-product.jsp").forward(req,resp);}catch(Exception e){throw new ServletException("Unable to save product. Check server console; existing DAO may need its product collection initialized.",e);}}
 private boolean blank(String s){return s==null||s.trim().isEmpty();}
}
